/bin/bash -lc "python3 - <<'PY'
import os
from pathlib import Path

session_file = Path.home() / \".codex/sessions/2026/10/09/rollout-2026-10-09T12-17-36-01a12098-f1dd-79e2-a366-ced48d20f35b.jsonl\"
open_descriptors = []
for process_dir in Path(\"/proc\").glob(\"[0-9]*\"):
    fd_dir = process_dir / \"fd\"
    if not fd_dir.is_dir():
        continue
    for descriptor in fd_dir.iterdir():
        try:
            target = os.readlink(descriptor)
        except OSError:
            continue
        if target == str(session_file):
            open_descriptors.append((process_dir.name, descriptor.name))

print(f\"open_session_descriptors={len(open_descriptors)}\")
try:
    session_file.unlink()
except FileNotFoundError:
    pass
if session_file.exists() or session_file.is_symlink():
    raise SystemExit(\"ERROR: session JSONL still exists\")
print(\"session_jsonl_removed=true\")
PY"

